using UnityEngine;
using UnityEditor;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            result.Log("project=" + Application.dataPath);
            if (Application.dataPath != "E:/VividRP_Reborn/Assets")
                return;
            string[] files = {"ScramblingTile1SPP", "RankingTile1SPP", "ScramblingTile8SPP", "RankingTile8SPP", "ScramblingTile256SPP", "RankingTile256SPP", "SobolOwenScrambled256"};
