            for (int i = 0; i < files.Length; i++)
            {
                string path = "Packages/com.vivid.render-pipelines/Texture/BlueNoise/" + files[i] + ".png";
                var tex = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
                var importer = AssetImporter.GetAtPath(path) as TextureImporter;
                var global = Shader.GetGlobalTexture(globals[i]);
                result.Log(files[i] + " present=" + (tex != null) + " size=" + tex.width + "x" + tex.height + " format=" + tex.graphicsFormat + " mip=" + tex.mipmapCount + " filter=" + tex.filterMode + " srgb=" + importer.sRGBTexture + " compression=" + importer.textureCompression + " bound=" + (global != null) + " sameAsset=" + (global == tex));
            }
        }
    }
}
